from pathlib import Path
p=Path('index.html')
s=p.read_text(encoding='utf-8')
start=s.find('<section id="view-absence" class="view">')
end=s.find('<section id="view-auto" class="view">', start)
if start<0 or end<0: raise SystemExit('absence section not found')
new='''<section id="view-absence" class="view absence-final-page"><div class="page-head absence-final-head"><div><div class="eyebrow">VERFÜGBARKEIT</div><h1>Abwesenheiten</h1><p>Urlaub, Krankheit, Frei, Fortbildung und Sperrzeiten planen und Konflikte früh erkennen.</p></div><button class="primary absence-main-action" onclick="openAbsenceDialog()">＋ Abwesenheit eintragen</button></div><div class="card absence-manage-card"><div class="absence-toolbar"><h3>Abwesenheiten verwalten</h3><select id="absencePeriod" onchange="renderAbsenceDashboard()"><option value="week">Diese Woche</option><option value="month">Dieser Monat</option><option value="all">Alle</option></select><select id="absenceTypeFilter" onchange="renderAbsenceDashboard()"><option value="">Alle Arten</option><option>Urlaub</option><option>Krank</option><option>Frei</option><option>Fortbildung</option><option>Sperrzeit</option><option>Sonderurlaub</option><option>Sonstiges</option></select></div><div class="absence-table-head"><span>Mitarbeiter</span><span>Art</span><span>Zeitraum</span><span>Status</span><span>Aktionen</span></div><div id="absencePanel" class="absence-table-body"></div></div><div class="absence-bottom-grid"><div class="card absence-summary-card"><div class="absence-summary-title"><span class="absence-summary-icon">▣</span><h3>Wochenkalender</h3></div><p>Übersicht der Abwesenheiten in dieser Woche.</p><div id="absenceCalendar"></div></div><div class="card absence-summary-card"><div class="absence-summary-title"><span class="absence-summary-icon">♢</span><h3>Konflikte & Auswirkungen</h3><span class="absence-count" id="absenceConflictCount">0</span></div><p id="absenceConflictSummary">Keine Konflikte in dieser Woche.</p><div id="absenceConflicts"></div></div></div></section>\n  '''
s=s[:start]+new+s[end:]
css=r'''<style id="absence-final-design-css">
.absence-final-page .page-head{align-items:center;margin-bottom:28px}.absence-main-action{padding:13px 22px;font-size:14px;border-radius:9px}.absence-manage-card{padding:18px 20px 12px;background:linear-gradient(180deg,#102033,#0e1b2c);border-color:#203b55}.absence-toolbar{display:flex;align-items:center;gap:10px;margin-bottom:24px}.absence-toolbar h3{margin:0 12px 0 0;font-size:17px}.absence-toolbar select{background:#0b1726;border:1px solid #29435e;color:#eef6ff;border-radius:8px;padding:10px 34px 10px 12px}.absence-table-head,.absence-row-final{display:grid;grid-template-columns:1.35fr .9fr 1.15fr .7fr .38fr;gap:18px;align-items:center}.absence-table-head{padding:0 10px 12px;color:#8fa5bf;font-size:12px;font-weight:700}.absence-row-final{padding:14px 10px;border-top:1px solid #21374f}.absence-row-final:first-child{border-top:1px solid #29445f}.absence-employee{display:flex;align-items:center;gap:12px}.absence-employee .avatar{width:38px;height:38px;background:#174a86;font-size:12px}.absence-employee b{display:block}.absence-employee small,.absence-period small{display:block;color:#8ea4bd;margin-top:3px}.absence-kind{display:inline-flex;align-items:center;gap:7px;border-radius:7px;padding:7px 10px;font-weight:700;font-size:12px;width:max-content;border:1px solid #14534f;background:#0e3636;color:#42e1c6}.absence-kind.sick{border-color:#7a3140;background:#351b26;color:#ff7285}.absence-kind.other{border-color:#43526b;background:#172336;color:#b9c7d8}.absence-status{display:inline-flex;width:max-content;border-radius:7px;padding:7px 10px;background:#0f3a36;color:#38dfc2;font-size:12px;font-weight:700}.absence-status.pending{background:#3b2e16;color:#ffc268}.absence-status.rejected{background:#3a1c24;color:#ff7788}.absence-delete{width:38px;height:38px;border:1px solid #923143;background:#2b1520;color:#ff6677;border-radius:8px;font-size:18px}.absence-bottom-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px}.absence-summary-card{padding:20px 22px;min-height:160px;background:linear-gradient(180deg,#102033,#0e1b2c);border-color:#203b55}.absence-summary-title{display:flex;align-items:center;gap:10px}.absence-summary-title h3{margin:0}.absence-summary-card p{color:#9bb0c7;margin:12px 0 16px}.absence-summary-icon{width:34px;height:34px;display:grid;place-items:center;border-radius:8px;background:#0c3a38;border:1px solid #17655e;color:#2ad9bd;font-weight:800}.absence-count{margin-left:2px;background:#0c3a38;color:#35e2c5;border-radius:999px;padding:2px 7px;font-size:11px}.absence-calendar-days{display:grid;grid-template-columns:repeat(7,1fr);gap:6px}.absence-cal-day{border:1px solid #20384f;border-radius:8px;padding:8px;background:#0c1725;min-height:56px}.absence-cal-day b{font-size:11px}.absence-cal-day small{display:block;color:#849ab3;margin-top:4px;font-size:10px}.absence-conflict-item{padding:9px 10px;border:1px solid #6f4523;background:#2b2015;border-radius:8px;margin-top:7px;color:#ffd090}.absence-empty{color:#87a0b9;font-size:12px;padding:8px 0}
@media(max-width:900px){.absence-table-head{display:none}.absence-row-final{grid-template-columns:1fr 1fr}.absence-bottom-grid{grid-template-columns:1fr}.absence-toolbar{flex-wrap:wrap}.absence-toolbar h3{width:100%}}
</style>'''
if 'id="absence-final-design-css"' not in s:s=s.replace('</head>',css+'\n</head>',1)
js=r'''<script id="absence-final-design-js">
function renderAbsenceDashboard(){
 const panel=document.getElementById('absencePanel'); if(!panel)return;
 const period=document.getElementById('absencePeriod')?.value||'week', tf=document.getElementById('absenceTypeFilter')?.value||'';
 const wd=currentWeekDates().map(iso), month=iso(weekStart).slice(0,7);
 let list=absences.filter(a=>!tf||a.type===tf);
 if(period==='week')list=list.filter(a=>absenceDates(a).some(d=>wd.includes(d)));
 if(period==='month')list=list.filter(a=>absenceDates(a).some(d=>d.startsWith(month)));
 panel.innerHTML=list.length?list.sort((a,b)=>(a.startDate||a.date).localeCompare(b.startDate||b.date)).map(a=>{
   const e=employees.find(x=>x.id===a.employeeId), dates=absenceDates(a), st=absenceStatus(a), kind=a.type==='Krank'?'sick':(['Urlaub','Frei','Fortbildung','Sperrzeit','Sonderurlaub'].includes(a.type)?'':'other');
   const label=a.type==='Krank'?'♡ Krank':a.type==='Urlaub'?'☂ Urlaub':a.type;
   const range=dates.length>1?`${new Date(dates[0]+'T00:00:00').toLocaleDateString('de-DE')} - ${new Date(dates.at(-1)+'T00:00:00').toLocaleDateString('de-DE')}`:new Date(dates[0]+'T00:00:00').toLocaleDateString('de-DE');
   return `<div class="absence-row-final"><div class="absence-employee"><div class="avatar">${(e?.first?.[0]||'')+(e?.last?.[0]||'')}</div><div><b>${e?e.first+' '+e.last:'Unbekannt'}</b><small>Personalnummer: ${e?.personnelNo||'—'}</small></div></div><div><span class="absence-kind ${kind}">${label}</span></div><div class="absence-period"><b>${range}</b><small>${dates.length} ${dates.length===1?'Tag':'Tage'}</small></div><div><span class="absence-status ${st==='Beantragt'?'pending':st==='Abgelehnt'?'rejected':''}">${st}</span></div><div><button class="absence-delete" title="Entfernen" onclick="deleteAbsenceEnhanced('${a.id}')">⌫</button></div></div>`
 }).join(''):'<div class="absence-empty">Keine Abwesenheiten im gewählten Zeitraum.</div>';
 const cal=document.getElementById('absenceCalendar');
 if(cal)cal.innerHTML=`<div class="absence-calendar-days">${wd.map((d,i)=>{const aa=absences.filter(a=>absenceOn(a,d)&&absenceStatus(a)!=='Abgelehnt');return `<div class="absence-cal-day"><b>${DAYS[i]} ${new Date(d+'T00:00:00').toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit'})}</b><small>${aa.length?aa.map(a=>{const e=employees.find(x=>x.id===a.employeeId);return `${e?.first||''} ${a.type}`}).join('<br>'):'Keine'}</small></div>`}).join('')}</div>`;
 const conflicts=[];absences.filter(a=>absenceStatus(a)!=='Abgelehnt').forEach(a=>{const e=employees.find(x=>x.id===a.employeeId);assignments.filter(x=>x.employeeId===a.employeeId&&absenceOn(a,x.date)).forEach(x=>conflicts.push({a,e,x}))});
 const cnt=document.getElementById('absenceConflictCount');if(cnt)cnt.textContent=conflicts.length;
 const summary=document.getElementById('absenceConflictSummary');if(summary)summary.textContent=conflicts.length?`${conflicts.length} Konflikt${conflicts.length===1?'':'e'} gefunden.`:'Keine Konflikte in dieser Woche.';
 const box=document.getElementById('absenceConflicts');if(box)box.innerHTML=conflicts.length?conflicts.map(c=>`<div class="absence-conflict-item">⚠ ${c.e?.first||''} ${c.e?.last||''} · ${new Date(c.x.date+'T00:00:00').toLocaleDateString('de-DE')} · ${c.x.type} trotz ${c.a.type}</div>`).join(''):'';
}
</script>'''
if 'id="absence-final-design-js"' not in s:s=s.replace('</body>',js+'\n</body>',1)
p.write_text(s,encoding='utf-8')
print('final absence design applied')